package dev.myjarvis.core;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class StudyFeedbackLifecycleTest extends StudyFeedbackFixtures {
    @Test void logoutClosesOriginalActiveFeedbackExactlyOnce(){saveTwo();UUID id=requestFeedback(0);long before=conversationVersion(targetConversation);try(var crypto=mockStatic(javax.crypto.Cipher.class);var transport=mockStatic(LocalInferenceClient.class)){context.getBean(AuthService.class).logout(session);crypto.verifyNoInteractions();transport.verifyNoInteractions();}assertEquals(0,feedbackClient.calls);assertEquals("REVOKED",feedbackRow(id).get("state"));assertEquals(before+4,conversationVersion(targetConversation));assertEquals(2L,db.queryForObject("SELECT count(*) FROM study_feedback_events WHERE feedback_id=?",Long.class,id));assertEquals("SESSION_REVOKED",db.queryForObject("SELECT reason_code FROM study_feedback_events WHERE feedback_id=? AND version=2",String.class,id));}
    @Test void loginRotationInvalidatesOnlyMatchingActiveSessionScope(){saveTwo();UUID id=requestFeedback(0);AuthService auth=context.getBean(AuthService.class);var next=auth.find(auth.issue(owner,true,session.hash()).token());assertNotNull(next);assertEquals("REVOKED",feedbackRow(id).get("state"));assertEquals("SESSION_ACTIVE",feedbackRow(id).get("phase_invalidation_scope"));assertEquals(1,((Number)feedbackRow(id).get("phase_initial_scope_contexts")).intValue());}
    @Test void ownerProfileInvalidatesHistoricalContextsBeforeTerminalReceipt(){saveTwo();UUID id=requestFeedback(0);long before=conversationVersion(targetConversation);context.getBean(OwnerProfileService.class).patch(session,UUID.randomUUID(),json(Map.of("expected_version",db.queryForObject("SELECT version FROM owners WHERE id=?",Long.class,owner),"display_name","Synthetic display")));var row=feedbackRow(id);assertEquals("REVOKED",row.get("state"));assertEquals("OWNER_ALL",row.get("phase_invalidation_scope"));assertEquals(before+5,conversationVersion(targetConversation));assertEquals(2,((Number)row.get("phase_initial_scope_contexts")).intValue());assertEquals(0L,db.queryForObject("SELECT count(*) FROM inference_contexts WHERE owner_id=? AND conversation_id=? AND state<>'INVALIDATED'",Long.class,owner,targetConversation));}
    @Test void actualMemoryInvalidationUsesTheSameOwnerWideClosure(){
        var intents=context.getBean(MemoryIntentService.class);Map<String,Object> createArgs=new LinkedHashMap<>();
        createArgs.put("scope","GLOBAL");createArgs.put("project_id",null);createArgs.put("key","synthetic.feedback.preference");createArgs.put("kind","PREFERENCE");createArgs.put("value","Synthetic first preference");createArgs.put("change_reason","Synthetic explicit owner form");createArgs.put("expected_generation",0);createArgs.put("revive_deleted",false);
        Map<String,Object> createBody=new LinkedHashMap<>();createBody.put("tool_id","memory.write");createBody.put("operation","CREATE");createBody.put("target_id",null);createBody.put("arguments",createArgs);
        var createIntent=intents.issue(session,UUID.randomUUID(),json(createBody));var created=memories.save(session,UUID.randomUUID(),null,json(Map.of("intent_id",createIntent.get("id"),"arguments",createArgs)),true);UUID memory=UUID.fromString(created.get("memory_id").toString());
        assertEquals(1L,memories.get(session,memory).get("version"));saveTwo();UUID id=requestFeedback(0);long before=conversationVersion(targetConversation);
        var reviseArgs=json(Map.of("value","Synthetic revised preference","change_reason","Synthetic owner revision","expected_version",1,"expected_generation",1));
        var reviseIntent=intents.issue(session,UUID.randomUUID(),json(Map.of("tool_id","memory.write","operation","REVISE","target_id",memory,"arguments",reviseArgs)));
        var revised=memories.save(session,UUID.randomUUID(),memory,json(Map.of("intent_id",reviseIntent.get("id"),"arguments",reviseArgs)),false);
        assertEquals("COMMITTED",revised.get("status"));assertEquals(2L,memories.get(session,memory).get("version"));assertEquals("Synthetic revised preference",memories.get(session,memory).get("value"));
        assertEquals(List.of("CREATED","REVISED"),db.queryForList("SELECT event_type FROM memory_invalidation_outbox WHERE owner_id=? AND memory_id=? ORDER BY version",String.class,owner,memory));
        assertEquals("REVOKED",feedbackRow(id).get("state"));assertEquals("OWNER_ALL",feedbackRow(id).get("phase_invalidation_scope"));assertEquals(before+5,conversationVersion(targetConversation));
        assertEquals(2L,db.queryForObject("SELECT invalidated_contexts::bigint FROM study_feedback_events WHERE feedback_id=? AND operation='REVOKE'",Long.class,id));assertEquals(0L,db.queryForObject("SELECT count(*) FROM inference_contexts WHERE owner_id=? AND state<>'INVALIDATED'",Long.class,owner));assertEquals(0,feedbackClient.calls);
    }
    @Test void executionPauseClosesFeedbackBeforeGenericBulkUpdates(){saveTwo();UUID id=requestFeedback(0);flow.pause(session,true);assertEquals("REVOKED",feedbackRow(id).get("state"));assertEquals("PAUSE_ACTIVE",feedbackRow(id).get("phase_invalidation_scope"));assertEquals(2L,db.queryForObject("SELECT version FROM runs WHERE id=?",Long.class,feedbackRow(id).get("run_id")));assertEquals(1L,db.queryForObject("SELECT count(*) FROM study_feedback_events WHERE feedback_id=? AND operation='REVOKE'",Long.class,id));}
    @Test void genericRunCancelHasOneClosedPhaseAndNoFabricatedOwnerReceipt(){saveTwo();UUID id=requestFeedback(0);var row=feedbackRow(id);UUID run=(UUID)row.get("run_id");flow.cancel(session,run,1);assertEquals("REVOKED",feedbackRow(id).get("state"));var event=db.queryForMap("SELECT * FROM study_feedback_events WHERE feedback_id=? AND operation='REVOKE'",id);assertEquals("RUN_CANCELLED",event.get("reason_code"));assertNull(event.get("idempotency_key"));assertNull(event.get("operation_session_hash"));assertFalse(quiescent(id));}
    @Test void staleForeignAndExpiredGenericCancelCannotCloseAnotherAuthority(){saveTwo();UUID id=requestFeedback(0);UUID run=(UUID)feedbackRow(id).get("run_id");error(()->flow.cancel(session,run,2),409,"PRECONDITION_CHANGED");assertThrows(ApiException.class,()->flow.cancel(session,UUID.randomUUID(),1));error(()->flow.tx.executeWithoutResult(s->{db.update("UPDATE sessions SET last_seen_at=clock_timestamp()-interval '2 hours' WHERE token_hash=?",session.hash());flow.cancel(session,run,1);}),401,"SESSION_REVOKED");assertEquals("ACTIVE",feedbackRow(id).get("output_authority"));}
    @Test void aNewLiveSessionMayRevokeButOnlyItsOwnOperationCanReconcile(){saveTwo();UUID id=requestFeedback(0);AuthService auth=context.getBean(AuthService.class);var second=auth.find(auth.issue(owner,true,null).token());UUID key=UUID.randomUUID();var result=feedback.revoke(second,key,id,revokeBody(id));assertEquals(receipt(result),receipt(feedback.mutation(second,key)));error(()->feedback.mutation(session,key),403,"AUTHORITY_NOT_VALID");assertEquals(session.hash(),feedbackRow(id).get("initiating_session_hash"));}
    @Test void duringTransportRevocationPreventsLateResponseRetention(){saveTwo();UUID id=requestFeedback(0);feedbackClient.duringInfer=()->context.getBean(AuthService.class).logout(session);assertTrue(feedbackLocal.runOne());assertEquals(1,feedbackClient.calls);assertEquals("REVOKED",feedbackRow(id).get("state"));assertNull(feedbackRow(id).get("result_ref"));assertEquals(1L,db.queryForObject("SELECT count(*) FROM inference_usage_receipts WHERE reservation_id=? AND receipt_kind='MEASURED'",Long.class,feedbackRow(id).get("reservation_id")));}
    @Test void acceptedHistoricalContextInvalidationDoesNotRewriteFeedbackHistory()throws Exception {saveTwo();UUID id=requestFeedback(0);complete(id);proof(id,"COMPLETED");var events=db.queryForList("SELECT * FROM study_feedback_events WHERE feedback_id=? ORDER BY version",id);String result=(String)feedbackRow(id).get("result_ref");flow.tx.executeWithoutResult(s->context.getBean(InferenceContextFreshness.class).invalidateOwner(owner,false));assertEquals("INVALIDATED",db.queryForObject("SELECT state FROM inference_contexts WHERE id=?",String.class,feedbackRow(id).get("context_id")));assertEquals(events,db.queryForList("SELECT * FROM study_feedback_events WHERE feedback_id=? ORDER BY version",id));assertEquals(result,feedbackRow(id).get("result_ref"));assertEquals("ACCEPTED",feedbackRow(id).get("state"));assertTrue(quiescent(id));assertNotNull(feedback.read(session,studyId));}
    private void projectChange(boolean deactivate) {
        UUID project=(UUID)context.getBean(ProjectService.class).create(session,UUID.randomUUID(),json(Map.of("name","Synthetic feedback project","description","Synthetic scope only"))).get("id");
        targetConversation=(UUID)flow.createConversation(session,json(Map.of("title","Project feedback source","project_id",project))).get("id");studyId=start(targetConversation,lesson(targetConversation));
        study.answer(session,UUID.randomUUID(),studyId,answerBody(studyId,0,"Synthetic project answer one"));study.answer(session,UUID.randomUUID(),studyId,answerBody(studyId,1,"Synthetic project answer two"));
        UUID id=requestFeedback(0);long before=conversationVersion(targetConversation);var original=feedbackRow(id);
        assertEquals(1,db.update(deactivate?"UPDATE projects SET active=false WHERE owner_id=? AND id=?":"UPDATE projects SET version=version+1 WHERE owner_id=? AND id=?",owner,project));
        var row=feedbackRow(id);assertEquals("REVOKED",row.get("state"));assertEquals("RUN_EXACT",row.get("phase_invalidation_scope"));assertEquals(before+4,conversationVersion(targetConversation));assertEquals(original.get("project_version"),row.get("project_version"));assertEquals(original.get("source_binding_ref"),row.get("source_binding_ref"));
        var event=db.queryForMap("SELECT * FROM study_feedback_events WHERE feedback_id=? AND operation='REVOKE'",id);assertEquals("SOURCE_INVALIDATED",event.get("reason_code"));assertEquals(1,((Number)event.get("invalidated_contexts")).intValue());assertNull(event.get("idempotency_key"));assertEquals(0,feedbackClient.calls);assertFalse(quiescent(id));
    }
    @Test void directProjectVersionChangeSynchronouslyClosesPinnedFeedback(){projectChange(false);}
    @Test void directProjectDeactivationSynchronouslyClosesPinnedFeedback(){projectChange(true);}
    @Test void failedHistoricalInvalidationPreservesErrorAndPermitsOnlySecondSavedTarget()throws Exception {
        saveTwo();UUID first=requestFeedback(0);feedbackClient.kind="ERROR";assertTrue(feedbackLocal.runOne());proof(first,"UNSTARTED_FENCED");var events=db.queryForList("SELECT * FROM study_feedback_events WHERE feedback_id=? ORDER BY version",first);var original=feedbackRow(first);
        context.getBean(OwnerProfileService.class).patch(session,UUID.randomUUID(),json(Map.of("expected_version",db.queryForObject("SELECT version FROM owners WHERE id=?",Long.class,owner),"display_name","Synthetic later profile")));
        assertEquals("INVALIDATED",db.queryForObject("SELECT state FROM inference_contexts WHERE id=?",String.class,original.get("context_id")));assertEquals(original,feedbackRow(first));assertEquals(events,db.queryForList("SELECT * FROM study_feedback_events WHERE feedback_id=? ORDER BY version",first));assertTrue(quiescent(first));assertThrows(ApiException.class,()->requestFeedback(0));UUID second=requestFeedback(1);assertEquals("ACTIVE",feedbackRow(second).get("output_authority"));assertEquals(2L,count("study_feedback_requests"));
    }
}
